#![allow(unused_imports)]
use verus::prelude::*;

/* is_smaller returns true exactly when, for every valid index i,
   arr1[i] > arr2[i].  We assume the two vectors have the same length. */
#[verifier(external_body)]
#[requires(arr1@.len() == arr2@.len())]
#[decreases(arr1@.len())]
#[ensures(result == (forall|i: usize| i < arr1@.len() ==> arr1@[i] > arr2@[i]))]
fn is_smaller(arr1: &Vec<i32>, arr2: &Vec<i32>) -> bool {
    // As the problem stipulates, we assume arr1.len() == arr2.len().
    // For empty arrays, this will correctly return true.
    arr1.iter()
        .zip(arr2.iter())
        .all(|(a, b)| a > b)
}

